{
  "title": "Coordination Chemistry Quiz",
  "questions": [
    {
      "question": "What determines the coordination number of a complex?",
      "options": [
        "The charge of the metal ion",
        "The number of sigma-donor atoms directly bonded to the metal",
        "The type of ligands used",
        "The overall charge of the complex"
      ],
      "correct_answer": "The number of sigma-donor atoms directly bonded to the metal",
      "explanation": "The coordination number is defined as the number of sigma-donor atoms that are directly bonded to the central metal atom in a coordination complex."
    },
    {
      "question": "In the complex [Fe(CN)6]4-, what is the coordination number?",
      "options": [
        "1",
        "4",
        "6",
        "8"
      ],
      "correct_answer": "6",
      "explanation": "The coordination number in the complex [Fe(CN)6]4- is 6, as indicated by the subscript '6' which represents the number of cyanide ligands bonded to the iron ion."
    },
    {
      "question": "According to IUPAC nomenclature, how should ligands be listed?",
      "options": [
        "By decreasing electronegativity",
        "In order of their complexity",
        "Alphabetically",
        "By the order they appear in the formula"
      ],
      "correct_answer": "Alphabetically",
      "explanation": "When naming coordination compounds according to IUPAC rules, the ligands are listed in alphabetical order before the metal."
    },
    {
      "question": "How are anionic ligands named according to IUPAC rules?",
      "options": [
        "By adding '-ide' to the end",
        "By replacing the final '-e' with '-o'",
        "By adding '-ate' to the end",
        "By using their common name"
      ],
      "correct_answer": "By replacing the final '-e' with '-o'",
      "explanation": "Anionic ligands are typically named by replacing the final '-e' of the anion's name with an '-o'."
    }
  ]
}

